const nextHuntByNewestRelease = `-- name: NextHuntByNewestRelease :many
SELECT desired_item_id, class, priority, last_searched_at, release_date,
       eligible_after, search_count, queued_since, after_failure
FROM hunt_queue
WHERE class = ?1 AND eligible_after <= ?2
  AND (CAST(?3 AS INTEGER) = 0 OR release_date >= ?3)
  AND (CAST(?4 AS INTEGER) = 0 OR release_date IS NULL OR release_date < ?4)
ORDER BY priority DESC, release_date DESC
LIMIT ?5
`

type NextHuntByNewestReleaseParams struct {
	Class         string
	Now           int64
	ReleaseFrom   int64
	ReleaseBefore int64
	PageSize      int64
}

// newest_release.
func (q *Queries) NextHuntByNewestRelease(ctx context.Context, arg NextHuntByNewestReleaseParams) ([]HuntQueue, error) {
	rows, err := q.db.QueryContext(ctx, nextHuntByNewestRelease,
		arg.Class,
		arg.Now,
		arg.ReleaseFrom,
		arg.ReleaseBefore,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []HuntQueue{}
	for rows.Next() {
		var i HuntQueue
		if err := rows.Scan(
			&i.DesiredItemID,
			&i.Class,
			&i.Priority,
			&i.LastSearchedAt,
			&i.ReleaseDate,
			&i.EligibleAfter,
			&i.SearchCount,
			&i.QueuedSince,
			&i.AfterFailure,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

